#!/usr/bin/env node
// generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
//
// Git-логика скриптов .claude/bin/: профиль репозитория из .claude/git-settings.json, база
// задачи, цель выпуска и проверка «влита ли ветка». Реализация одна на все скрипты: .mjs
// импортируют модуль, shell-скрипты зовут
//
//   node .claude/bin/lib/git.mjs resolve   <корень> <репо> [<КОД>]   # база, цель MR, выпуск
//   node .claude/bin/lib/git.mjs defaults  <корень> <репо>           # профиль и ветки с сервера
//   node .claude/bin/lib/git.mjs task      <корень> <КОД>            # базы из git-flow.md задачи, без сети
//   node .claude/bin/lib/git.mjs merged    <корень> <репо> <ветка> <цель> …
//   node .claude/bin/lib/git.mjs protected <корень> <репо>
//   node .claude/bin/lib/git.mjs detect    <корень> <репо>           # сигналы и предложение профиля (setup)
//
// и читают строки «<ключ>\t<значение>». Механика профилей — .claude/reference/git-flow.md.
// Скрипт, который обходит много задач, зовёт defaults по разу на репозиторий и task по разу
// на задачу: сеть нужна только первому.
//
// Хранится только то, чего git сказать не может: профиль репозитория. Ветка по умолчанию
// берётся с сервера (ls-remote), цель выпуска dev-default — та из master/main, что есть
// на origin. Записанная копия этих имён разошлась бы с хостингом молча.

import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { loadWorkspace } from './workspace.mjs';

export const FLOWS = ['main-default', 'dev-default', 'custom'];
const RELEASE_TARGETS = ['master', 'main'];
const NETWORK_TIMEOUT_MS = 20000;

export function git(cwd, args, { network = false } = {}) {
  const r = spawnSync('git', ['-C', cwd, ...args], {
    encoding: 'utf8',
    timeout: network ? NETWORK_TIMEOUT_MS : 0,
    env: { ...process.env, GIT_TERMINAL_PROMPT: '0' },
  });
  return { ok: r.status === 0, code: r.status, out: (r.stdout || '').trim(), err: (r.stderr || '').trim() };
}

const readJson = (file, problems) => {
  if (!fs.existsSync(file)) return { exists: false, json: {} };
  try {
    const json = JSON.parse(fs.readFileSync(file, 'utf8'));
    if (json === null || typeof json !== 'object' || Array.isArray(json)) {
      problems.push({ fatal: true, msg: `${path.basename(file)}: корень — не объект` });
      return { exists: true, json: {} };
    }
    return { exists: true, json };
  } catch (e) {
    problems.push({ fatal: true, msg: `${path.basename(file)} не разбирается: ${e.message}` });
    return { exists: true, json: {} };
  }
};

export function loadGitSettings(root) {
  const problems = [];
  const shared = readJson(path.join(root, '.claude', 'git-settings.json'), problems);
  const local = readJson(path.join(root, '.claude', 'git-settings.local.json'), problems);
  const soft = (msg) => problems.push({ fatal: false, msg });
  const fatal = (msg) => problems.push({ fatal: true, msg });

  for (const k of Object.keys(shared.json)) {
    if (!['standArchive', 'removeSourceBranch', 'repos'].includes(k)) soft(`git-settings.json: неизвестный ключ ${k}`);
  }
  for (const k of Object.keys(local.json)) {
    if (k !== 'reviewers') soft(`git-settings.local.json: неизвестный ключ ${k}`);
  }

  const bool = (key, def) => {
    if (!(key in shared.json)) return def;
    if (typeof shared.json[key] !== 'boolean') { fatal(`git-settings.json: ${key} — ждётся true или false`); return def; }
    return shared.json[key];
  };

  const repos = {};
  if ('repos' in shared.json) {
    const r = shared.json.repos;
    if (r === null || typeof r !== 'object' || Array.isArray(r)) {
      fatal('git-settings.json: repos — ждётся объект «репозиторий → профиль»');
    } else {
      for (const [name, flow] of Object.entries(r)) {
        if (!FLOWS.includes(flow)) { fatal(`git-settings.json: repos.${name} — «${flow}» не одно из ${FLOWS.join(' · ')}`); continue; }
        repos[name] = flow;
      }
    }
  }

  let reviewers;
  if ('reviewers' in local.json) {
    const r = local.json.reviewers;
    if (r === null || typeof r !== 'object' || Array.isArray(r)) {
      fatal('git-settings.local.json: reviewers — ждётся объект «репозиторий → [логины]»');
    } else {
      reviewers = {};
      for (const [name, list] of Object.entries(r)) {
        if (!Array.isArray(list) || list.some((x) => typeof x !== 'string')) { fatal(`git-settings.local.json: reviewers.${name} — ждётся массив логинов`); continue; }
        reviewers[name] = list;
      }
    }
  }

  return {
    exists: shared.exists,
    localExists: local.exists,
    standArchive: bool('standArchive', false),
    removeSourceBranch: bool('removeSourceBranch', true),
    repos,
    reviewers,
    problems,
  };
}

// Профиль, которого нет в git-settings.json, — main-default: так работал движок до профилей,
// и проект без файла настроек не ломается. workspace-check называет такой репозиторий.
export const flowOf = (settings, repo) => settings.repos[repo] ?? 'main-default';

// Ветка по умолчанию на сервере. Локальный origin/HEAD записан при клонировании и сам
// не обновляется, когда ветку по умолчанию на хостинге меняют, — он лишь запасной путь без сети.
export function serverDefault(repoAbs) {
  const r = git(repoAbs, ['ls-remote', '--symref', 'origin', 'HEAD'], { network: true });
  const m = r.ok && r.out.match(/^ref: refs\/heads\/(\S+)\tHEAD$/m);
  if (m) return { branch: m[1], source: 'сервер' };
  const local = git(repoAbs, ['symbolic-ref', '--short', 'refs/remotes/origin/HEAD']);
  if (local.ok && local.out.startsWith('origin/')) {
    return { branch: local.out.slice('origin/'.length), source: 'локальный origin/HEAD — сервер не ответил, имя могло устареть' };
  }
  return { branch: null, source: 'ветку по умолчанию не узнать: сервер не ответил, origin/HEAD не задан' };
}

// Цель выпуска dev-default: master или main, которая есть на origin. Обе сразу — не догадка:
// это либо свой флоу (custom), либо лишняя ветка, и решает человек.
export function releaseTarget(repoAbs) {
  const r = git(repoAbs, ['ls-remote', '--heads', 'origin', ...RELEASE_TARGETS], { network: true });
  if (!r.ok) return { branch: null, problem: 'сервер не ответил на ls-remote — цель выпуска не узнать' };
  const found = RELEASE_TARGETS.filter((b) => new RegExp(`\\srefs/heads/${b}$`, 'm').test(r.out));
  if (found.length === 1) return { branch: found[0] };
  if (found.length === 0) return { branch: null, problem: 'на origin нет ни master, ни main — профиль dev-default не подходит, нужен custom' };
  return { branch: null, problem: 'на origin есть и master, и main — это свой флоу (custom) или лишняя ветка, решает человек' };
}

// memory/tasks/<КОД>/git-flow.md: строка таблицы «| <репо> | <база> | <выпуск> |». Прочерк —
// по профилю. Файла нет — всё по профилю. Читается только таблица с заголовком
// «Репозиторий | База»: в файле бывают и другие таблицы, и их строки дали бы мусор вместо базы.
export function taskOverrides(root, tasksDir, code) {
  const file = path.join(root, tasksDir, code, 'git-flow.md');
  if (!fs.existsSync(file)) return { file: null, rows: {} };
  const rows = {};
  let inTable = false;
  for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
    const cells = line.split('|').slice(1, -1).map((c) => c.trim().replace(/^`|`$/g, ''));
    if (cells.length < 2) { inTable = false; continue; }
    if (cells[0] === 'Репозиторий' && cells[1] === 'База') { inTable = true; continue; }
    if (!inTable || /^:?-+:?$/.test(cells[0])) continue;
    const dash = (v) => (v === undefined || v === '' || v === '—' || v === '-' ? null : v);
    rows[cells[0]] = { base: dash(cells[1]), release: dash(cells[2]) };
  }
  return { file: path.relative(root, file).split(path.sep).join('/'), rows };
}

export function resolve(root, repoName, code) {
  const ws = loadWorkspace(root);
  const settings = loadGitSettings(root);
  const repo = ws.repos.find((r) => r.name === repoName);
  if (!repo) return { problem: `репозитория «${repoName}» нет: ${ws.repos.map((r) => r.name).join(', ') || 'список пуст'}` };
  const repoAbs = path.join(root, repo.path);
  const flow = flowOf(settings, repoName);
  const out = { repo: repoName, path: repo.path, flow, notes: [] };

  const task = code ? taskOverrides(root, ws.config.tasksDir, code) : { file: null, rows: {} };
  const row = task.rows[repoName] ?? {};

  if (row.base) {
    out.base = row.base;
    out.baseSource = task.file;
  } else if (flow === 'custom') {
    return { ...out, problem: `профиль custom: база задачи не записана в ${task.file ?? `${ws.config.tasksDir}/${code ?? '<КОД>'}/git-flow.md`} — её пишет task-start по memory/commands/git.md` };
  } else {
    const d = serverDefault(repoAbs);
    if (!d.branch) return { ...out, problem: d.source };
    out.base = d.branch;
    out.baseSource = `ветка по умолчанию (${d.source})`;
  }
  out.mr = out.base;

  if (flow === 'dev-default') {
    const t = releaseTarget(repoAbs);
    if (t.branch) out.release = t.branch;
    else out.notes.push(t.problem);
    out.releaseMode = row.release ?? 'плановый';
  }
  return out;
}

// Влита ли ветка в цель: по предкам (ветка влита перемоткой или merge-коммитом) или по
// содержимому патча — git cherry не находит у ветки ни одного коммита, которого нет в цели
// (ветка влита ребейзом или cherry-pick'ом, хеши другие). Схлопывание на хостинге первому
// не попадает, второму — только если ветка уже была одним коммитом: поэтому team-lead
// схлопывает сам до push (git-flow.md, «Коммиты»).
export function isMerged(repoAbs, branch, target) {
  if (git(repoAbs, ['merge-base', '--is-ancestor', branch, target]).ok) return { merged: true, by: 'предок' };
  const c = git(repoAbs, ['cherry', target, branch]);
  if (!c.ok) return { merged: false, by: `git cherry: ${c.err || 'ошибка'}` };
  const ahead = c.out.split('\n').filter((l) => l.startsWith('+'));
  return ahead.length === 0 ? { merged: true, by: 'патч' } : { merged: false, by: `невлитых коммитов: ${ahead.length}` };
}

// Коммиты прежней вершины oldRef, у которых в истории newRef нет пары: ни коммита с тем же
// патчем — git patch-id --stable переживает смену хеша при ребейзе и cherry-pick, — ни коммита
// с той же темой — она переживает правку патча на конфликте. Пара ищется среди коммитов новой
// истории после общего предка, поэтому влитое в основную ветку, на которую переложен стенд,
// пропажей не считается. Ту же проверку делает барьер guard-push перед push с силой — алгоритм
// у них один, правится в обоих местах.
export function lostCommits(repoAbs, oldRef, newRef) {
  const sha = (ref) => git(repoAbs, ['rev-parse', '--verify', '--quiet', `${ref}^{commit}`]);
  const o = sha(oldRef);
  const n = sha(newRef);
  if (!o.ok) return { problem: `нет коммита ${oldRef}` };
  if (!n.ok) return { problem: `нет коммита ${newRef}` };
  const out = { old: o.out, new: n.out, lost: [] };
  if (git(repoAbs, ['merge-base', '--is-ancestor', o.out, n.out]).ok) return out;
  const mb = git(repoAbs, ['merge-base', o.out, n.out]);
  if (!mb.ok) return { ...out, unrelated: true };

  const patchIds = (range) => {
    const log = spawnSync('git', ['-C', repoAbs, 'log', '--no-merges', '--no-color', '--no-ext-diff', '-p', '--format=commit %H', ...range],
      { encoding: 'utf8', maxBuffer: 1 << 30 });
    const ids = spawnSync('git', ['patch-id', '--stable'], { input: log.stdout || '', encoding: 'utf8', maxBuffer: 1 << 28 });
    return (ids.stdout || '').split('\n').filter(Boolean).map((l) => l.split(' '));
  };
  const newIds = new Set(patchIds([n.out, `^${mb.out}`]).map(([id]) => id));
  const newSubjects = new Set(git(repoAbs, ['log', '--no-merges', '--format=%s', n.out, `^${mb.out}`]).out.split('\n'));
  const oldIds = new Map(patchIds([o.out, `^${n.out}`]).map(([id, c]) => [c, id]));
  for (const l of git(repoAbs, ['log', '--no-merges', '--format=%h%x09%H%x09%s', o.out, `^${n.out}`]).out.split('\n').filter(Boolean)) {
    const [short, full, subject] = l.split('\t');
    if (newIds.has(oldIds.get(full)) || newSubjects.has(subject)) continue;
    out.lost.push({ short, subject });
  }
  return out;
}

// Сигналы для выбора профиля при setup: ветка по умолчанию и ветки master/main/dev — у сервера
// и по именам (длинный список веток на выводе не обрезать нечему), история — по последним
// коммитам первой линии. Окно короткое намеренно: флоу репозитория меняется, и merge-коммиты
// dev полугодовой давности под линейной историей последних месяцев — прошлое, а не профиль.
// Ветки берутся fetch'ем с явным refspec: у клона с узким refspec (--single-branch)
// origin/master может не быть вовсе. Меняются только ссылки origin/*, рабочее дерево — нет.
const DETECT_WINDOW = 10;
const DEV_MERGE = /^Merge (?:branch '(?:dev|develop)'|remote-tracking branch 'origin\/(?:dev|develop)')/;

export function detect(repoAbs) {
  const out = { notes: [] };
  const d = serverDefault(repoAbs);
  out.default = d.branch;
  out.defaultSource = d.source;
  const local = git(repoAbs, ['symbolic-ref', '--short', 'refs/remotes/origin/HEAD']);
  if (d.source === 'сервер' && local.ok && local.out !== `origin/${d.branch}`) {
    out.notes.push(`локальный ${local.out} устарел: на сервере ветка по умолчанию — ${d.branch}`);
  }
  const names = [...RELEASE_TARGETS, 'dev'];
  const heads = git(repoAbs, ['ls-remote', '--heads', 'origin', ...names], { network: true });
  out.heads = heads.ok ? names.filter((b) => new RegExp(`\\srefs/heads/${b}$`, 'm').test(heads.out)) : [];
  if (!heads.ok) out.notes.push('сервер не ответил на ls-remote — ветки master/main/dev не узнать');

  const history = (branch) => {
    const ref = `refs/remotes/origin/${branch}`;
    const f = git(repoAbs, ['fetch', '-q', 'origin', `+refs/heads/${branch}:${ref}`], { network: true });
    if (!f.ok && !git(repoAbs, ['rev-parse', '--verify', '-q', ref]).ok) return null;
    const log = git(repoAbs, ['log', '--first-parent', `-n${DETECT_WINDOW}`, '--format=%p%x09%ad%x09%s', '--date=short', ref]);
    if (!log.ok) return null;
    const rows = log.out.split('\n').filter(Boolean).map((l) => {
      const [parents, date, subject] = l.split('\t');
      return { merge: parents.trim().includes(' '), date, subject };
    });
    const lastDev = git(repoAbs, ['log', '--first-parent', '--merges', '-n1', '--format=%ad', '--date=short', '-E',
      "--grep=^Merge (branch '(dev|develop)'|remote-tracking branch 'origin/(dev|develop)')", ref]);
    return {
      branch,
      window: rows.length,
      direct: rows.filter((r) => !r.merge).length,
      devMerges: rows.filter((r) => r.merge && DEV_MERGE.test(r.subject)).length,
      otherMerges: rows.filter((r) => r.merge && !DEV_MERGE.test(r.subject)).length,
      lastCommit: rows[0]?.date ?? null,
      lastDevMerge: lastDev.ok && lastDev.out ? lastDev.out : null,
      stale: !f.ok,
    };
  };
  const say = (h) => `${h.branch}: последние ${h.window} коммитов первой линии — прямых ${h.direct}, merge из dev ${h.devMerges}, других merge ${h.otherMerges}; последний merge из dev — ${h.lastDevMerge ?? 'нет'}${h.stale ? ' (fetch не прошёл, история локальная)' : ''}`;

  const releases = RELEASE_TARGETS.filter((b) => out.heads.includes(b));
  const propose = (flow, reason) => { out.proposal = flow; out.reason = reason; };
  if (!d.branch) {
    propose(null, 'ветку по умолчанию не узнать — профиль спросить у человека');
  } else if (releases.length === 2) {
    propose('custom', 'на origin есть и master, и main — свой флоу или лишняя ветка, решает человек');
  } else if (RELEASE_TARGETS.includes(d.branch)) {
    const h = history(d.branch);
    if (h) out.notes.push(say(h));
    if (!h) propose(null, `история ${d.branch} недоступна — профиль спросить у человека`);
    else if (h.devMerges > 0 && h.devMerges >= h.direct) {
      propose('custom', `работа приходит в ${d.branch} merge-коммитами из dev, а ветка по умолчанию — ${d.branch}: dev-default требует dev веткой по умолчанию на сервере — смени её или опиши флоу`);
    } else {
      propose('main-default', `ветка по умолчанию ${d.branch}, свежая история без вливаний dev — задачи идут в ${d.branch}`);
    }
  } else if (d.branch === 'dev') {
    if (releases.length === 0) propose('custom', 'ветка по умолчанию dev, но на origin нет ни master, ни main — выпускать некуда');
    else {
      const h = history(releases[0]);
      if (h) out.notes.push(say(h));
      propose('dev-default', `ветка по умолчанию dev, выпуск — ${releases[0]}`);
    }
  } else {
    propose('custom', `ветка по умолчанию ${d.branch} — не master, main или dev`);
  }
  return out;
}

// Ветки, push в которые закрыт: ветка по умолчанию и, если есть на origin, master/main.
export function protectedBranches(root, repoName) {
  const ws = loadWorkspace(root);
  const repo = ws.repos.find((r) => r.name === repoName);
  if (!repo) return [];
  const repoAbs = path.join(root, repo.path);
  const set = new Set();
  const d = serverDefault(repoAbs);
  if (d.branch) set.add(d.branch);
  const r = git(repoAbs, ['ls-remote', '--heads', 'origin', ...RELEASE_TARGETS], { network: true });
  for (const b of RELEASE_TARGETS) if (r.ok && new RegExp(`\\srefs/heads/${b}$`, 'm').test(r.out)) set.add(b);
  return [...set];
}

const isMain = (() => {
  try {
    return Boolean(process.argv[1]) && fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url));
  } catch { return false; }
})();

if (isMain) {
  const [cmd, rootArg, repo, ...rest] = process.argv.slice(2);
  const usage = 'использование: node lib/git.mjs resolve|defaults|task|merged|protected|detect <корень> <репо> …\n';
  if (!cmd || !rootArg || !repo) { process.stderr.write(usage); process.exit(2); }
  const root = path.resolve(rootArg);
  const repoAbsOf = (name) => {
    const r = loadWorkspace(root).repos.find((x) => x.name === name);
    if (!r) { process.stderr.write(`репозитория «${name}» нет\n`); process.exit(2); }
    return path.join(root, r.path);
  };
  const print = (o) => {
    for (const [k, v] of Object.entries(o)) {
      if (v === undefined || v === null) continue;
      if (Array.isArray(v)) for (const x of v) process.stdout.write(`${k}\t${x}\n`);
      else process.stdout.write(`${k}\t${v}\n`);
    }
  };
  if (cmd === 'resolve') {
    const r = resolve(root, repo, rest[0]);
    print(r);
    process.exit(r.problem ? 1 : 0);
  } else if (cmd === 'defaults') {
    const abs = repoAbsOf(repo);
    const flow = flowOf(loadGitSettings(root), repo);
    const d = flow === 'custom' ? { branch: null } : serverDefault(abs);
    const t = flow === 'dev-default' ? releaseTarget(abs) : {};
    print({ flow, base: d.branch, release: t.branch });
  } else if (cmd === 'task') {
    // Второй аргумент здесь — код задачи, а не репозиторий.
    const { rows } = taskOverrides(root, loadWorkspace(root).config.tasksDir, repo);
    for (const [name, r] of Object.entries(rows)) process.stdout.write(`${name}\t${r.base ?? '-'}\t${r.release ?? '-'}\n`);
  } else if (cmd === 'merged') {
    const [branch, ...targets] = rest;
    if (!branch || targets.length === 0) { process.stderr.write(usage); process.exit(2); }
    const abs = repoAbsOf(repo);
    for (const t of targets) {
      const m = isMerged(abs, branch, t);
      process.stdout.write(`${t}\t${m.merged ? 'влита' : 'нет'}\t${m.by}\n`);
    }
  } else if (cmd === 'detect') {
    const r = detect(repoAbsOf(repo));
    print({ default: r.default, defaultSource: r.defaultSource, heads: r.heads.join(' ') || '—', proposal: r.proposal ?? '—', reason: r.reason, note: r.notes });
  } else if (cmd === 'protected') {
    print({ protected: protectedBranches(root, repo) });
  } else {
    process.stderr.write(usage);
    process.exit(2);
  }
}
